package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result); // 123 octal = 83 decimal
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   0755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 8);
        assertEquals(493L, result); // 755 octal = 493 decimal
    }

    @Test
    public void testParseOctal_ZeroBuffer() {
        byte[] buffer = new byte[]{0, 0, 0};
        long result = TarUtils.parseOctal(buffer, 0, 3);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "0".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test
    public void testParseOctal_MaxLongValue() {
        // Testing a large octal value
        byte[] buffer = "777777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 12);
        assertEquals(140737488355311L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "0080".getBytes(); // 8 is invalid in octal
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_NonDigit() {
        byte[] buffer = "00A0".getBytes();
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_EmptyAfterSpaces() {
        byte[] buffer = "    ".getBytes();
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test
    public void testParseOctal_OffsetUsage() {
        byte[] buffer = "junk00123junk";
        // Start at index 4, length 5 -> "00123"
        long result = TarUtils.parseOctal(buffer, 4, 5);
        assertEquals(10L, result); // 123 octal = 10 decimal? No, 123 octal is 83. 
        // Let's re-calculate: 1*64 + 2*8 + 3 = 64 + 16 + 3 = 83.
        // Wait, my previous mental math was wrong. Let's use 00123 -> 1*64 + 2*8 + 3 = 83.
        // Let's use 00010 -> 8.
        byte[] buffer2 = "junk00010junk".getBytes();
        assertEquals(8L, TarUtils.parseOctal(buffer2, 4, 5));
    }

    @Test
    public void testParseOctal_TrailingSpaces() {
        // The code has a logic: trailer = buffer[end-1]. 
        // While (start < end && (trailer == 0 || false))
        // Since 'false' is always false, the loop 'while (start < end && (trailer == 0 || false))'
        // effectively only runs if trailer == 0.
        // This means trailing spaces are NOT trimmed by the NUL loop, 
        // but the main loop will hit ' ' and throw IllegalArgumentException 
        // because ' ' is not between '0' and '7'.

        // However, let's test the behavior as written.
        byte[] buffer = "000123 ".getBytes(); 
        try {
            TarUtils.parseOctal(buffer, 0, 7);
            fail("Should have thrown exception because space is not octal");
        } catch (IllegalArgumentException e) {
            // Expected
        }
    }

    @Test
    public void testParseOctal_TrailingNUL() {
        // The loop 'while (start < end && (trailer == 0 || false))'
        // If the last byte is 0, end decrements.
        byte[] buffer = {'0', '0', '1', '0', 0}; 
        // offset 0, length 5. end = 5. buffer[4] is 0.
        // end becomes 4. trailer becomes buffer[3] ('0'). Loop stops.
        // result = 0010 (octal) = 8.
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(8L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_AllNULs() {
        // If all are NULs, the loop might reduce end until start == end
        byte[] buffer = {0, 0, 0};
        // buffer[0] is 0, returns 0L immediately based on the first if(buffer[start] == 0)
        // To trigger the start == end exception, we need buffer[start] != 0 but trailing NULs
        byte[] buffer2 = {'1', 0, 0};
        // start=0, end=3. buffer[2]=0. end=2. trailer=buffer[1]=0. end=1. trailer=buffer[0]='1'.
        // Loop stops. result = 1.
        // To trigger start == end, we need to bypass the buffer[start]==0 check.
        byte[] buffer3 = {' ', 0, 0}; 
        // buffer[0] is ' ', so it skips to start=1. 
        // end=3. trailer=0. end=2. trailer=0. end=1. trailer=' '.
        // start=1, end=1. start == end. Throws exception.
        TarUtils.parseOctal(buffer3, 0, 3);
    }
}
